using System;

namespace StdbModule;

public static partial class ItalianQuotes
{
    public static class AlessandroManzoni
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://it.wikiquote.org/wiki/Alessandro_Manzoni", Text = "Il principio, di necessità tanto più indeterminato quanto più esteso mi sembra poter essere questo: che la poesia e la letteratura in genere debba proporsi l'utile per iscopo, il vero per soggetto e l'interessante per mezzo.", Author = "Alessandro Manzoni" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alessandro_Manzoni", Text = "Liberi non sarem se non siamo uni.", Author = "Alessandro Manzoni" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alessandro_Manzoni", Text = "Per tutta Italia si scrive e si parla una lingua comune. E quegli stessi che ne fanno questione e ricerca, come lo fanno di grazia? Scrivendo in questa lingua medesima.", Author = "Alessandro Manzoni" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alessandro_Manzoni", Text = "Quando esce in campo una dizione nuova, strana, la qual non pretenda se non fare il medesimo uffizio che già è fatto da un'altra, convien ributtarla, soffocarla, non lasciarla allignare, se si può.", Author = "Alessandro Manzoni" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alessandro_Manzoni", Text = "Il forte si mesce col vinto nemico, col nuovo signore rimane l'antico; l'un popolo e l'altro sul collo vi sta.", Author = "Alessandro Manzoni" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alessandro_Manzoni", Text = "Gli estinti, Ansberga, talor de' vivi son più forti assai.", Author = "Alessandro Manzoni" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alessandro_Manzoni", Text = "Amor tremendo è il mio. Tu nol conosci ancora; oh! tutto ancora non tel mostrai; tu eri mio: secura nel mio gaudio io tacea; né tutta mai questo labbro pudico osato avria dirti l'ebbrezza del mio cor segreto.", Author = "Alessandro Manzoni" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alessandro_Manzoni", Text = "Sparsa le trecce morbide Sull'affannoso petto, Lenta le palme, e rorida Di morte il bianco aspetto, Giace la pia, col tremolo Sguardo cercando il ciel.", Author = "Alessandro Manzoni" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alessandro_Manzoni", Text = "Gran segreto è la vita, e nol comprende che l'ora estrema.", Author = "Alessandro Manzoni" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alessandro_Manzoni", Text = "Godi che re non sei, godi che chiusa all'oprar t'è ogni via: loco a gentile, ad innocente opra non v'è: non resta che far torto, o patirlo.", Author = "Alessandro Manzoni" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alessandro_Manzoni", Text = "Le vie di Dio son molte, Più assai di quelle del mortal.", Author = "Alessandro Manzoni" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alessandro_Manzoni", Text = "Quella via, Su cui ci pose il ciel, correrla intera Convien, qual ch'ella sia, fino all'estremo.", Author = "Alessandro Manzoni" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alessandro_Manzoni", Text = "Il mio cor m'ange, Anfrido: ei mi comanda alte e nobili cose; e la fortuna mi condanna ad inique.", Author = "Alessandro Manzoni" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alessandro_Manzoni", Text = "Non sempre ciò che vien dopo è progresso.", Author = "Alessandro Manzoni" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alessandro_Manzoni", Text = "È difficile, in qualunque grado, vuol sempre dire possibile.", Author = "Alessandro Manzoni" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alessandro_Manzoni", Text = "Il raziocinio è un lume che uno può accendere, quando vuole obbligar gli altri a vedere, e può soffiarci sopra, quando non vuol più veder lui.", Author = "Alessandro Manzoni" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alessandro_Manzoni", Text = "Fu vera gloria? Ai posteri l'ardua sentenza.", Author = "Alessandro Manzoni" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alessandro_Manzoni", Text = "Il Dio che atterra e suscita, Che affanna e che consola.", Author = "Alessandro Manzoni" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alessandro_Manzoni", Text = "Sì, la prudenza è la virtù dei vecchi: ella cresce cogli anni, e tanto cresce che alfin diventa... paura.", Author = "Alessandro Manzoni" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alessandro_Manzoni", Text = "I fratelli hanno ucciso i fratelli: Questa orrenda novella vi do.", Author = "Alessandro Manzoni" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alessandro_Manzoni", Text = "S'ode a destra uno squillo di tromba; A sinistra risponde uno squillo.", Author = "Alessandro Manzoni" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alessandro_Manzoni", Text = "Ahi sventura! sventura! sventura!", Author = "Alessandro Manzoni" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alessandro_Manzoni", Text = "Deh! vogli la via segnarmi, onde toccar la cima io possa, o far che, s'io cadrò su l'erta, dicasi almen: su l'orma propria ei giace.", Author = "Alessandro Manzoni" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alessandro_Manzoni", Text = "Il santo Vero Mai non tradir; né proferir mai verbo ! Che plauda al vizio o la virtù derida.", Author = "Alessandro Manzoni" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alessandro_Manzoni", Text = "S'ode un carme: l'intento Isaia Proferì questo sacro lamento, In quel dì che un divino spavento Gli affannava il fatidico cor.", Author = "Alessandro Manzoni" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alessandro_Manzoni", Text = "Egli è il Giusto, che i vili han trafitto, Ma tacente, ma senza tenzone; Egli è il Giusto; e di tutti il delitto Il Signor sul suo capo versò.", Author = "Alessandro Manzoni" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alessandro_Manzoni", Text = "Disse Iddio: Qual chiedete sarà. E quel Sangue dai padri imprecato Sulla misera prole ancor cade, Che, mutata d'etade in etade, Scosso ancor dal suo capo non l'ha.", Author = "Alessandro Manzoni" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alessandro_Manzoni", Text = "Madre de' Santi, immagine Della città superna, Del sangue incorruttibile Conservatrice eterna; Tu che, da tanti secoli, Soffri, combatti e preghi, Che le tue tende spieghi Dall'uno all'altro mar;", Author = "Alessandro Manzoni" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alessandro_Manzoni", Text = "Perché, baciando i pargoli, La schiava ancor sospira? E il sen che nutre i liberi Invidïando mira? Non sa che al regno i miseri Seco il Signor solleva? Che a tutti i figli d'Eva Nel suo dolor pensò?", Author = "Alessandro Manzoni" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alessandro_Manzoni", Text = "È un giudizio della più rea e stolta temerità l'affermare d'alcun uomo vivente, che non lo sia, l'escluderne uno solo dalla speranza nelle ricchezze delle misericordie di Dio.", Author = "Alessandro Manzoni" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alessandro_Manzoni", Text = "La maldicenza rende peggiore chi parla e chi ascolta, e per lo più anche chi n'è l'oggetto.", Author = "Alessandro Manzoni" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alessandro_Manzoni", Text = "Il dubbio parziale e accidentale limita la scienza: il dubbio universale e necessario la nega.", Author = "Alessandro Manzoni" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alessandro_Manzoni", Text = "Il vero male per l'uomo non è quello che soffre, ma quello che fa.", Author = "Alessandro Manzoni" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alessandro_Manzoni", Text = "Le ingiurie hanno un gran vantaggio sui ragionamenti, ed è quello di essere ammesse senza prova da una moltitudine di lettori.", Author = "Alessandro Manzoni" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alessandro_Manzoni", Text = "Uno dei tormenti degli uomini d'ingegno è che quando una verità è stata detta essi prevedono che finirà a prevalere, e intanto devono assistere alla lunga nojosa insopportabile guerra che le si fa.", Author = "Alessandro Manzoni" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alessandro_Manzoni", Text = "Bisogna cominciare a dire le verità che non urtino di fronte le opinioni false predominanti: dirne molte molte di queste verità.", Author = "Alessandro Manzoni" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alessandro_Manzoni", Text = "Ma la menzogna, l'abuso del potere, la violazion delle leggi e delle regole più note e ricevute, l'adoprar doppio peso e doppia misura, son cose che si posson riconoscere anche dagli uomini negli atti umani.", Author = "Alessandro Manzoni" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alessandro_Manzoni", Text = "Ci par di vedere la natura umana spinta invincibilmente al male da cagioni indipendenti dal suo arbitrio, e come legata in un sogno perverso e affannoso, da cui non ha mezzo di riscotersi.", Author = "Alessandro Manzoni" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alessandro_Manzoni", Text = "L'operar senza regole è il più faticoso e difficile mestiere di questo mondo.", Author = "Alessandro Manzoni" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alessandro_Manzoni", Text = "Non si lavora a fare e a ritagliar finimenti al cavallo che si vuol lasciar correre a suo capriccio; gli si leva la briglia, se l'ha.", Author = "Alessandro Manzoni" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alessandro_Manzoni", Text = "Ciò ch'essi chiamavano arbitrio, era in somma la cosa stessa che, per iscansar quel vocabolo equivoco e di tristo suono, fu poi chiamata poter discrezionale.", Author = "Alessandro Manzoni" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alessandro_Manzoni", Text = "Viene, nelle cose grandi, come nelle piccole, un momento in cui ciò che, essendo accidentale e fattizio, vuol perpetuarsi come naturale e necessario, è costretto a cedere all'esperienza, al ragionamento, alla sazietà, alla moda.", Author = "Alessandro Manzoni" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alessandro_Manzoni", Text = "E non paia strano di vedere un tribunale farsi seguace ed emulo d'una o di due donnicciole; giacché, quando s'è per la strada della passione, è naturale che i più ciechi guidino.", Author = "Alessandro Manzoni" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alessandro_Manzoni", Text = "Spegnere il lume è un mezzo opportunissimo per non veder la cosa che non piace, ma non per veder quella che si desidera.", Author = "Alessandro Manzoni" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alessandro_Manzoni", Text = "Ma il mantello dell'iniquità è corto; e non si può tirarlo per ricoprire una parte, senza scoprirne un'altra.", Author = "Alessandro Manzoni" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alessandro_Manzoni", Text = "Chi ti ha dato il comando ti promette egli il soccorso.", Author = "Alessandro Manzoni" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alessandro_Manzoni", Text = "Confida tanto più, quanto più ti senti debole, perché il Signore non manca a chi si conosce e prega.", Author = "Alessandro Manzoni" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alessandro_Manzoni", Text = "O Vergine, o Signora, o Tuttasanta, Che bei nomi ti serba ogni loquela! Più d'un popol superbo esser si vanta in tua gentil tutela.", Author = "Alessandro Manzoni" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alessandro_Manzoni", Text = "Tu pur, beata, un dì provasti il pianto; Né il dì verrà che d'oblianza il copra; Anco ogni giorno se ne parla; e tanto Secol vi corse sopra.", Author = "Alessandro Manzoni" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alessandro_Manzoni", Text = "Alessandro Manzoni quando sentiva esaltare un libro domandava col suo fine sorriso canzonatore: lo rileggereste?", Author = "Alessandro Manzoni" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alessandro_Manzoni", Text = "Com'è possibile accusare il Manzoni di pietismo considerando la profonda tenerezza cristiana che irrora il cuore del poeta e gli strappa accenti giusti e soavi e potenti insieme?", Author = "Alessandro Manzoni" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alessandro_Manzoni", Text = "Aveva paura del dentista; epperò, quando aveva bisogno dell'opera sua, si faceva mettere a posto la chiave da lui, e si cavava il dente da sé.", Author = "Alessandro Manzoni" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alessandro_Manzoni", Text = "Dimostrossi il Manzoni precocemente avverso al matrimonio. A nove anni, trovandosi a un pranzo di gala, gli accadde di versare il bicchiere sulla tavola.", Author = "Alessandro Manzoni" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alessandro_Manzoni", Text = "Fanciullo «impressionabile,» ancora negli ultimi suoi anni conservava vivo nella fantasia il lugubre quadro dei Francesi che aveva veduto battere in ritirata davanti agli Austriaci.", Author = "Alessandro Manzoni" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alessandro_Manzoni", Text = "Il Manzoni possedeva in alto grado quella ch'egli chiama «la virtù dei vecchi» cioè la prudenza.", Author = "Alessandro Manzoni" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alessandro_Manzoni", Text = "Vecchio cadente, ben sentendo come il corpo e l'intelletto fossero esauriti, andava ripetendo agli amici: «Rido di me, piangendo».", Author = "Alessandro Manzoni" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alessandro_Manzoni", Text = "Nella terza delle cinque giornate di Milano segnò francamente il suo nome in un foglio diretto dai Milanesi al re Carlo Alberto per invocarne l'ajuto; ma poco dopo non volle sottoscrivere il plebiscito dell'unione della Lombardia col Piemonte.", Author = "Alessandro Manzoni" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alessandro_Manzoni", Text = "La storia è un \"immenso pelago di errori\". La denuncia veniva dall'illuminismo giuridico.", Author = "Alessandro Manzoni" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alessandro_Manzoni", Text = "Tutti gli errori, Manzoni compendia nella storia morale e politica del Seicento: l'incertezza del diritto, la legislazione eccessivamente proliferante che a colpi di gride sopporta l'arbitrio dei potenti e la manipolazione dei causidici.", Author = "Alessandro Manzoni" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Alessandro_Manzoni", Text = "Ma don Lisander non era tipo da cedere e assecondare senza una sua convinzione. Nel progetto della moglie e del figliastro, lo allettava il proposito di un ritratto \"conversato\".", Author = "Alessandro Manzoni" },
        };
    }
}